import { Injectable } from '@angular/core';
import { CanActivate, Router, UrlTree } from '@angular/router';
import { Observable, map } from 'rxjs';
import { AuthState } from 'app/services/auth-state';
import { UamService } from 'app/services/uam';

@Injectable({ providedIn: 'root' })
export class WebshieldGuard implements CanActivate {
    constructor(
        private uamService: UamService,
        private authState: AuthState,
        private router: Router,
    ) {}

    canActivate(): Observable<boolean | UrlTree> {
        return this.uamService.cachedStatus().pipe(
            map(status => {
                const allowed = this.authState.isAdmin.value
                    ? !!status
                    : !!status?.allowed_for_users;
                return allowed || this.router.parseUrl('/');
            }),
        );
    }
}
