import { Component, ViewChild } from '@angular/core';
import { LoaderDirective } from 'app/utils/loader/loader.directive';
import { AppState } from 'app/core/app.service';
import { I360Config } from 'app/utils/config/config';
import { ModalService } from 'app/utils/modals/modal.service';
import { finalize, take } from 'rxjs';
import { configsEqual } from 'app/utils/configs-equal';
import { NotificationsService } from 'app/services/notifications';
import { PortBlockingMode } from '@imunify360-api/settings';
import { IP_VERSION } from 'app/utils/ip-version-toggle/ip-version.enum';
import {
    BlockedPortsModalComponent,
} from 'app/components/blocked-ports/blocked-ports-modal/blocked-ports-modal.component';


@Component({
    selector: 'i360-blocked-ports-form',
    templateUrl: './blocked-ports-form.component.html',
    styleUrls: [`./blocked-ports-form.component.scss`,
        `../../settings/settings-index.component.scss`],
    host: {
        class: 'display-block'
    },
})
export class BlockedPortsFormComponent {
    @ViewChild(LoaderDirective, {static: false}) loader: LoaderDirective;

    PortBlockingMode = PortBlockingMode;
    IP_VERSION = IP_VERSION;
    selectedIpVersion = IP_VERSION.V4;

    constructor(
        public appState: AppState,
        public i360Config: I360Config,
        private modalService: ModalService,
        private notifications: NotificationsService,
    ) {}

    configChanged() {
        if (this.appState.csf) {
            return false;
        }

        const originalConfig = this.i360Config.configRef._configChange.getValue()?.FIREWALL;
        const changedConfig = this.i360Config.schema.value?.FIREWALL;

        if (!originalConfig || !changedConfig || changedConfig?.port_blocking_mode !== PortBlockingMode.deny) {
            return false;
        }

        const relatedFields = [
            'port_blocking_mode',
            'TCP_IN_IPv4',
            'TCP_OUT_IPv4',
            'UDP_IN_IPv4',
            'UDP_OUT_IPv4',
            'TCP_IN_IPv6',
            'TCP_OUT_IPv6',
            'UDP_IN_IPv6',
            'UDP_OUT_IPv6',
        ];

        const originalValues = relatedFields.reduce((acc, key) => {
            acc[key] = originalConfig[key];
            return acc;
        }, {} as Record<string, any>);

        const changedValues = relatedFields.reduce((acc, key) => {
            acc[key] = changedConfig[key];
            return acc;
        }, {} as Record<string, any>);

        return !configsEqual(originalValues, changedValues);
    }

    submit() {
        if (this.i360Config.schema.value.FIREWALL.port_blocking_mode === PortBlockingMode.allow) {
            return this.updateConfig();
        }

        this.modalService.open(BlockedPortsModalComponent, {
            data: {
                form: this.i360Config.schema.value.FIREWALL,
                ipVersion: this.selectedIpVersion,
            },
        }).then((result) => {
            if (result) {
                this.updateConfig()
            }
        });
    }

    onChangeBlockingMode(portBlockingMode: PortBlockingMode) {
        if (portBlockingMode === PortBlockingMode.allow) {
            // wait for hide unnecessary fields from the form
            setTimeout(() => {
                this.updateConfig();
            }, 10)
        }
    }

    private updateConfig() {
        this.loader.show('blocked-ports-form');
        this.i360Config.save(false).pipe(
            take(1),
            finalize(() => {
                this.loader.hide('blocked-ports-form');
            }),
        ).subscribe(() => {
            this.notifications.success(
                'settings.successSaveMessage',
            ).then();
        });
    }
}
